UPDATE "products" SET "en" = '{"name":"Alocasia melo","lead":"Alocasia melo has thick, rigid grey-green leaves with a rough, rhino-skin texture and deeply sunken veins. Compact and slow-growing, it is a collector''s favourite for desks and shelves with indirect light. The sap irritates skin, so keep it away from children and pets.","spec":"Desk · Indoor","specs":[["Light","Bright indirect light; avoid direct sun, which scorches the leaves"],["Watering","Water when the top 2–3cm of soil is dry, about 1–2 times a week; the thick leaves cope with dryness better than other Alocasia, but waterlogging rots the tuber"],["Soil","A very free-draining, low-soil mix: pine bark or coco chips, coco coir, perlite, pumice"],["Feeding","Half-strength diluted NPK 20-20-20 once a month while putting out new leaves"],["Temperature & humidity","Best at 20–30°C, likes high humidity; keep out of direct air-conditioner draughts"],["Care level","Moderate — needs a consistently bright spot"],["Growth rate","Slow"],["Mature size","30–60cm tall"],["Pet safety","No — the sap irritates skin and is toxic if chewed (calcium oxalate crystals)"],["Uses","Desks, shelves; an unusual collector''s foliage plant"],["Propagation","Separate small tubers, divide"],["Origin","Rainforests of Sabah, Borneo (Malaysia)"],["Scientific name","Alocasia melo"],["Common pests & diseases","Red spider mites, mealybugs; tuber rot if waterlogged"],["Best for","Foliage collectors, lovers of unusual leaves"]],"fengshui":{"meaning":"Thick, sturdy leaves symbolising steadiness, endurance and luck","placement":"Desk, bookshelf"}}'::jsonb WHERE "slug" = 'mon-melo' AND "en" IS NULL;
