UPDATE "products" SET "en" = '{"name":"Alocasia ''Polly'' (Môn quan âm)","lead":"Alocasia ''Polly'' has near-black, glossy arrow-shaped leaves with bold silvery-white veins and purple undersides. Compact, it suits desks, shelves and living rooms with indirect light. The sap irritates skin, so keep it away from children and pets.","spec":"Desk · Office · Indoor","specs":[["Light","Bright indirect light near a window; harsh direct sun scorches the leaves, long periods of low light make the stems stretch and the leaves fade"],["Watering","Water when the top 2–3cm of soil is dry, about twice a week; the tuber rots easily if waterlogged, never leave water standing in the saucer"],["Soil","A very free-draining mix: coco coir, pine bark or coco chips, perlite, a little worm castings"],["Feeding","Half-strength diluted NPK 20-20-20 every 2–4 weeks while putting out new leaves; stop feeding in the cool season"],["Temperature & humidity","Best at 18–30°C, likes high humidity, mist around the plant; below 15°C it may drop leaves and the tuber may rot"],["Care level","Moderate — needs a consistently bright spot"],["Growth rate","Moderate"],["Mature size","40–60cm tall"],["Pet safety","No — the sap irritates skin and is toxic if chewed (calcium oxalate crystals)"],["Uses","Desks, shelves, living rooms; a handsome collector''s plant and gift"],["Propagation","Separate small tubers, divide"],["Origin","Ornamental hybrid of Southeast Asian Alocasia species"],["Scientific name","Alocasia × amazonica ''Polly''"],["Common pests & diseases","Red spider mites in hot dry air, mealybugs; tuber rot if waterlogged; leaves yellow and drop just after being moved"],["Best for","People who like beautiful foliage and have time to care for it"]],"fengshui":{"meaning":"Upright leaves with striking silver veins; seen in folk belief as bringing luck and prosperity","placement":"Desk, shelf, living room"}}'::jsonb WHERE "slug" = 'mon-quan-am' AND "en" IS NULL;
