UPDATE "products" SET "en" = '{"name":"Aglaonema ''Silver Queen'' (Ngân hậu)","lead":"''Silver Queen'' Aglaonema has long leaves covered in silver patches and green, in a compact clump. Very shade-tolerant, it thrives in air-conditioned offices.","spec":"Office · Indoor","specs":[["Light","Bright indirect light, tolerates shade well; avoid harsh direct sun, which scorches the leaves"],["Watering","Water when the top 2–3cm of soil is dry, about 2–3 times a week; never leave water standing in the saucer"],["Soil","Loose, free-draining mix: clean soil with coco coir, burnt rice husk and worm castings"],["Feeding","Slow-release fertiliser or diluted NPK 20-20-20, once a month"],["Height","30–50cm"],["Temperature & humidity","Best at 18–32°C, likes humidity; keep out of direct air-conditioner draughts"],["Care level","Easy care"],["Growth rate","Moderate"],["Mature size","30–60cm tall"],["Pet safety","No — the sap irritates skin and is toxic if chewed (calcium oxalate crystals)"],["Uses","Desks, shelves, room corners, offices"],["Propagation","Division, stem or tip cuttings"],["Origin","Southeast Asia"],["Scientific name","Aglaonema (''Silver Queen'' type)"],["Common pests & diseases","Root rot if waterlogged, mealybugs, red spider mites; yellow leaves after long periods of low light"],["Best for","Beginners, low-light offices"]],"fengshui":{"meaning":"Silver tones symbolising elegance, peace and prosperity","placement":"Living room, desk"}}'::jsonb WHERE "slug" = 'ngan-hau' AND "en" IS NULL;
