UPDATE "products" SET "en" = '{"name":"Jade plant (Crassula ovata)","lead":"Jade plant has thick, round, glossy succulent leaves and a stem that turns woody over time, so it can be shaped as a bonsai. Drought-tolerant, loves bright sun and lives for many years.","spec":"Office · Desk · Indoor","specs":[["Light","4–6 hours of sun a day; with too little sun it stretches and loses colour"],["Watering","Water when the soil is completely dry, about once a week (less in the rainy season); keep water out of the leaf joints"],["Soil","Fast-draining mix: fine gravel, perlite and burnt rice husk with a little soil"],["Feeding","Light dose of slow-release fertiliser every 1–2 months"],["Temperature & humidity","Best at 15–35°C, likes it dry and airy; long rainy spells cause rot"],["Care level","Easy care — just enough sun and little water"],["Growth rate","Slow"],["Mature size","20–60cm tall, woody stem"],["Pet safety","No — mildly toxic to cats and dogs"],["Uses","Desks, windows, balconies, mini bonsai"],["Propagation","Stem or leaf cuttings"],["Origin","South Africa"],["Scientific name","Crassula ovata"],["Common pests & diseases","Root rot if waterlogged, mealybugs in the leaf joints"],["Best for","Beginners, sunny desks"]],"fengshui":{"meaning":"Round, coin-like leaves symbolising wealth and abundance","placement":"Desk near a window, south-east corner"}}'::jsonb WHERE "slug" = 'ngoc-bich' AND "en" IS NULL;
