UPDATE "products" SET "en" = '{"name":"Nam Viet slow-release fertiliser NPK 18-8-22, 150g jar","lead":"Nam Viet (Rynan) NPK 18-8-22 slow-release fertiliser. High potassium helps plants flower, sweetens fruit and strengthens stems. For fruit trees and potted ornamentals.","spec":"High potassium · 150g jar","specs":[["Composition","N 18% · P₂O₅ 8% · K₂O 22%"],["Dosage","3–5g per small pot; 5–10g per 1–2-year-old plant; 10–20g per large plant"],["Reapply","After 45–90 days"],["Suitable for","Fruit trees, flowering plants, potted ornamentals"],["Brand","Nam Viet (Rynan)"],["Shelf life","36 months from the production date"]],"body":[{"text":"Features","type":"h2"},{"text":"**High potassium (K₂O 22%)** helps plants flower, makes fruit firm and sweet, and strengthens stems. Best used as plants prepare to flower and set fruit.","type":"p"},{"text":"What is slow-release fertiliser?","type":"h2"},{"text":"Each granule is coated with a polymer film. When you water, moisture passes through the coating, dissolves the nutrients inside and releases them slowly around the roots. Plants are fed evenly every day instead of getting one big dose as with fast-release fertiliser, so there is **less root burn and less fertiliser washed away** — and you only need to feed every few months, ideal for busy people or gardens with many pots.","type":"p"},{"text":"Suggested dosage","type":"h2"},{"rows":[["Plant","Amount per application"],["Small pot","3–5g"],["1–2-year-old plant","5–10g per plant"],["Large plant","10–20g per plant"]],"type":"table"},{"text":"How to apply","type":"h2"},{"type":"list","items":["Scatter evenly over the pot surface, **3–5cm from the stem**, keeping granules off the stem and young roots.","Cover with a thin layer of potting mix or press the granules lightly into the soil.","Water thoroughly straight after feeding — the granules only release nutrients when moist.","Reapply after **45–90 days**."],"ordered":true},{"text":"Do not reapply before the release period is over. Overdosing burns roots and yellows leaf edges. Keep the bag sealed, store in a dry place out of the sun, away from children and pets.","type":"note","title":"Note"},{"text":"Need advice on dosage for a particular plant? Message [the shop on Zalo](https://zalo.me/0703005001) or read [our guide to choosing fertilisers](/goc-cham-cay?chuyen-muc=thuoc-phan-bon).","type":"p"}]}'::jsonb WHERE "slug" = 'phan-bon-nam-viet-npk-18-8-22' AND "en" IS NULL;
--> statement-breakpoint
UPDATE "products" SET "en" = '{"name":"Rynan Flowermate 230 slow-release fertiliser NPK 23-08-08+TE","lead":"Rynan Flowermate 230 slow-release fertiliser, NPK 23-08-08 + trace elements. High nitrogen for lush, green leaves. Polymer-coated granules release nutrients evenly for about 4 months — ideal for foliage, indoor and office plants.","spec":"Foliage plants · 4-month slow release","specs":[["Composition","N 23% · P₂O₅ 8% · K₂O 8% + trace elements (TE)"],["Dosage","Scatter 5–20g around the base depending on plant size, 3–5cm from the stem, then water"],["Release period","About 120 days"],["Suitable for","Foliage plants, indoor plants, office plants"],["Brand","Rynan"],["Shelf life","36 months from the production date"]],"body":[{"file":"https://antinnong.com/wp-content/uploads/2026/07/phan-tan-cham-rynan-230-npk-23-8-8-1-25kg-an-tin-nong-1.png","type":"image","caption":"Rynan 230 slow-release fertiliser – NPK 23-08-08+TE"},{"text":"Why choose Rynan 230 for foliage plants?","type":"h2"},{"text":"The **high-nitrogen (N 23%)** formula is exactly what plants need when putting out leaves and shoots. New leaves open broad and dark green on sturdy stems; 8% phosphorus and potassium keep roots growing and branches firm. Trace elements (TE) help prevent deficiency yellowing.","type":"p"},{"text":"What is slow-release fertiliser?","type":"h2"},{"text":"Each granule is coated with a polymer film. When you water, moisture passes through the coating, dissolves the nutrients inside and releases them slowly around the roots. Plants are fed evenly every day instead of getting one big dose as with fast-release fertiliser, so there is **less root burn and less fertiliser washed away** — and you only need to feed every few months, ideal for busy people or gardens with many pots.","type":"p"},{"file":"https://antinnong.com/wp-content/uploads/2026/07/phan-tan-cham-rynan-230-npk-23-8-8-1-25kg-an-tin-nong-2.png","type":"image","caption":"Polymer-coated granules release nutrients for about 120 days"},{"text":"Composition","type":"h2"},{"rows":[["Nutrient","Content","Effect"],["Nitrogen (N)","23%","Leaves, shoots, green colour"],["Phosphorus (P₂O₅)","8%","Root growth"],["Potassium (K₂O)","8%","Sturdier plants, better resilience"],["Trace elements (TE)","Yes","Prevents physiological yellowing"]],"type":"table"},{"text":"Suggested dosage","type":"h2"},{"rows":[["Plant / pot size","Amount per application"],["Desk pots, orchids (≤ 15cm)","5–10g (1–2 teaspoons)"],["20–30cm pots","10–20g"],["Large plants, young fruit trees","20–30g, scattered around the canopy edge"],["Vegetables in boxes or trays","10–20g mixed into the topsoil"]],"type":"table"},{"file":"https://antinnong.com/wp-content/uploads/2026/07/phan-tan-cham-rynan-230-npk-23-8-8-1-25kg-an-tin-nong-3.png","type":"image","caption":"Scatter around the pot surface, 3–5cm from the stem"},{"text":"How to apply","type":"h2"},{"type":"list","items":["Scatter evenly over the pot surface, **3–5cm from the stem**, keeping granules off the stem and young roots.","Cover with a thin layer of potting mix or press the granules lightly into the soil.","Water thoroughly straight after feeding — the granules only release nutrients when moist.","Reapply after about **4 months**."],"ordered":true},{"file":"https://antinnong.com/wp-content/uploads/2026/07/phan-tan-cham-rynan-230-npk-23-8-8-1-25kg-an-tin-nong-4.png","type":"image","caption":"Rynan 230 for foliage, indoor and office plants"},{"text":"Do not reapply before the release period is over. Overdosing burns roots and yellows leaf edges. Keep the bag sealed, store in a dry place out of the sun, away from children and pets.","type":"note","title":"Note"},{"text":"Need advice on dosage for a particular plant? Message [the shop on Zalo](https://zalo.me/0703005001) or read [our guide to choosing fertilisers](/goc-cham-cay?chuyen-muc=thuoc-phan-bon).","type":"p"}]}'::jsonb WHERE "slug" = 'phan-tan-cham-rynan-flowermate-230' AND "en" IS NULL;
--> statement-breakpoint
UPDATE "products" SET "en" = '{"name":"Rynan Flowermate 240 slow-release fertiliser NPK 14-14-14+TE","lead":"Rynan Flowermate 240 slow-release fertiliser, balanced NPK 14-14-14 + trace elements, feeding leaves, roots and flowers. Polymer-coated granules release nutrients for about 3 months — ideal for roses, flowering plants and potted ornamentals.","spec":"Flowers · 3-month slow release","specs":[["Composition","N 14% · P₂O₅ 14% · K₂O 14% + trace elements (TE)"],["Dosage","5–10g per small pot, 10–20g per large plant; scatter around the base, then water"],["Release period","About 90 days"],["Suitable for","Roses, flowering plants, potted ornamentals"],["Brand","Rynan"],["Shelf life","36 months from the production date"]],"body":[{"file":"https://antinnong.com/wp-content/uploads/2025/06/phan-tan-cham-rynan-240-npk-14-14-14-90gr-an-tin-nong-1.png","type":"image","caption":"Rynan 240 slow-release fertiliser – NPK 14-14-14+TE"},{"text":"Why choose Rynan 240?","type":"h2"},{"text":"The **balanced 14-14-14** formula feeds leaves, roots and flowers alike — ideal for roses, flowering plants and potted ornamentals that need steady blooms while keeping good foliage. It does not push leaf growth as hard as high-nitrogen fertilisers, so plants stay compact and bud easily.","type":"p"},{"text":"What is slow-release fertiliser?","type":"h2"},{"text":"Each granule is coated with a polymer film. When you water, moisture passes through the coating, dissolves the nutrients inside and releases them slowly around the roots. Plants are fed evenly every day instead of getting one big dose as with fast-release fertiliser, so there is **less root burn and less fertiliser washed away** — and you only need to feed every few months, ideal for busy people or gardens with many pots.","type":"p"},{"file":"https://antinnong.com/wp-content/uploads/2025/06/phan-tan-cham-rynan-240-npk-14-14-14-90gr-an-tin-nong-2.png","type":"image","caption":"Coated Rynan 240 granules release nutrients for about 90 