UPDATE "products" SET "en" = '{"name":"Rynan slow-release fertiliser NPK 19-19-09, 150g jar","lead":"Rynan NPK 19-19-09 slow-release fertiliser with polymer-coated granules; high nitrogen and phosphorus help plants root, shoot and grow leaves and stems.","spec":"High phosphorus · 150g jar","specs":[["Composition","N 19% · P₂O₅ 19% · K₂O 9%"],["Dosage","Scatter around the base according to plant size, about 5–20g per pot, then water"],["Suitable for","Young plants, plants rooting and putting out shoots"],["Brand","Rynan"],["Shelf life","36 months from the production date"]],"body":[{"text":"Features","type":"h2"},{"text":"**High nitrogen and phosphorus (19-19)** help young plants root strongly and shoot quickly — ideal for newly planted or repotted plants and plants recovering.","type":"p"},{"text":"What is slow-release fertiliser?","type":"h2"},{"text":"Each granule is coated with a polymer film. When you water, moisture passes through the coating, dissolves the nutrients inside and releases them slowly around the roots. Plants are fed evenly every day instead of getting one big dose as with fast-release fertiliser, so there is **less root burn and less fertiliser washed away** — and you only need to feed every few months, ideal for busy people or gardens with many pots.","type":"p"},{"text":"Suggested dosage","type":"h2"},{"rows":[["Plant","Amount per application"],["Young plants, small pots","5–10g"],["20–30cm pots","10–20g"]],"type":"table"},{"text":"How to apply","type":"h2"},{"type":"list","items":["Scatter evenly over the pot surface, **3–5cm from the stem**, keeping granules off the stem and young roots.","Cover with a thin layer of potting mix or press the granules lightly into the soil.","Water thoroughly straight after feeding — the granules only release nutrients when moist.","Reapply after about **3 months**."],"ordered":true},{"text":"Do not reapply before the release period is over. Overdosing burns roots and yellows leaf edges. Keep the bag sealed, store in a dry place out of the sun, away from children and pets.","type":"note","title":"Note"},{"text":"Need advice on dosage for a particular plant? Message [the shop on Zalo](https://zalo.me/0703005001) or read [our guide to choosing fertilisers](/goc-cham-cay?chuyen-muc=thuoc-phan-bon).","type":"p"}]}'::jsonb WHERE "slug" = 'phan-tan-cham-rynan-npk-19-19-09' AND "en" IS NULL;
