UPDATE "products" SET "en" = '{"name":"Arrowhead plant, white (Syngonium podophyllum)","lead":"White arrowhead plant has arrow-shaped leaves of pale green washed with silvery white. Compact, shade-tolerant and easy to care for — great on desks, bookshelves, windowsills or grown in water.","spec":"Desk · Indoor","specs":[["Light","Indirect light, copes with office lighting; avoid harsh direct sun, which scorches the leaves"],["Watering","Water when the top 2–3cm of soil is dry, about twice a week; do not waterlog"],["Soil","Loose mix: clean soil with coco coir and burnt rice husk; can also grow in water"],["Feeding","Diluted NPK 20-20-20, once a month"],["Temperature & humidity","Best at 18–30°C, likes humidity"],["Care level","Easy care"],["Pet safety","No — the sap contains calcium oxalate crystals, irritates skin and is toxic if chewed"],["Uses","Desks, shelves, windows; can be grown in water"],["Propagation","Cuttings"],["Origin","Central and South America"],["Scientific name","Syngonium podophyllum"],["Common pests & diseases","Root rot if waterlogged; mealybugs and red spider mites in hot dry weather"]],"fengshui":{"meaning":"Cool silvery-white leaves, symbolising calm and peace","placement":"Desk, bookshelf, window"}}'::jsonb WHERE "slug" = 'troc-bac' AND "en" IS NULL;
--> statement-breakpoint
UPDATE "products" SET "en" = '{"name":"Song of India (Dracaena reflexa)","lead":"Song of India has slender stems in a clump with small leaves spiralling around them, glossy green or edged yellow. Elegant and neat, it suits living-room corners, offices and lobbies, and is believed to bring peace and luck.","spec":"Office · Indoor","specs":[["Light","Indirect light, fine indoors; avoid harsh sun, which scorches the leaves"],["Watering","Water when the top 2–3cm of soil is dry, twice a week; do not waterlog"],["Soil","Loose, free-draining mix: clean soil with coco coir and burnt rice husk"],["Feeding","Diluted NPK 20-20-20, once a month"],["Temperature & humidity","Best at 18–32°C"],["Care level","Easy care"],["Pet safety","No — toxic to cats and dogs if eaten"],["Uses","Room corners, offices, lobbies"],["Propagation","Cuttings"],["Scientific name","Dracaena reflexa"],["Common pests & diseases","Root rot if waterlogged; dry leaf tips when the air is too dry"]]}'::jsonb WHERE "slug" = 'truc-bach-hop' AND "en" IS NULL;
--> statement-breakpoint
UPDATE "products" SET "en" = '{"name":"Siam tulip (Curcuma alismatifolia)","lead":"Siam tulip is a ginger-family plant with long slender leaves and pink-purple tulip-like flowers on tall stems that last for weeks in the rainy season. Great in pots on sunny balconies and gardens.","spec":"Balcony · Garden","specs":[["Light","Gentle to bright sun; harsh midday sun scorches the leaf edges"],["Watering","Keep the soil evenly moist while in leaf and flower; in the dry season the leaves die back and the rhizome rests — water less"],["Soil","Loose, humus-rich, well-drained soil so the rhizome does not rot"],["Feeding","Diluted NPK every 2 weeks while in leaf, more phosphorus before flowering"],["Care level","Moderate"],["Uses","Balcony and garden pots, cut flowers"],["Propagation","Divide the rhizomes"],["Origin","Thailand, Cambodia"],["Scientific name","Curcuma alismatifolia"],["Temperature & humidity","Best at 22–35°C, likes warm, humid rainy-season weather"],["Growth rate","Moderate; the rhizome rests and the leaves die back in the dry season"],["Mature size","40–60cm tall"],["Common pests & diseases","Rhizome rot if waterlogged, aphids, leaf-eating caterpillars"],["Best for","People who like unusual flowers, sunny balconies and gardens"]],"fengshui":{"meaning":"Elegant pink-purple flowers, meaning luck and a good start","placement":"Balcony, front yard, entrance"}}'::jsonb WHERE "slug" = 'tulip-thai' AND "en" IS NULL;
--> statement-breakpoint
UPDATE "products" SET "en" = '{"name":"Lemon cypress (Cupressus macrocarpa ''Goldcrest'')","lead":"Lemon cypress has a conical shape and soft golden-green needles that release a lemony scent when gently crushed. Popular as a Christmas plant; suits balconies and bright windows.","spec":"Office · Indoor · Garden","specs":[["Light","Gentle to direct sun; indoors, place next to a bright window"],["Watering","Keep the soil slightly moist, water once a day in the dry season; never let it dry out completely"],["Soil","Sandy loam rich in humus, well drained"],["Feeding","Well-rotted manure every 2–3 months, extra NPK when flowering"],["Temperature & humidity","Likes it cool; long spells of intense heat can scorch the tips"],["Care level","Easy care"],["Growth rate","Moderate"],["Mature size","30cm–1.5m tall, conical"],["Uses","Balconies, windows, Christmas decoration"],["Propagation","Cuttings, air layering"],["Origin","California (USA)"],["Scientific name","Cupressus macrocarpa ''Goldcrest''"],["Common pests & diseases","Mealybugs, leaf-eating caterpillars, leaf fungus in the rainy season"],["Best for","People who like fragrant plants, bright balconies"]],"fengshui":{"meaning":"Symbolises endurance and longevity","placement":"Balcony, entrance"}}'::jsonb WHERE "slug" = 'tung-thom' AND "en" IS NULL;
