UPDATE "products" SET "en" = '{"name":"Croton, gold-spot (Codiaeum variegatum)","lead":"Gold-spot croton has long, glossy green leaves speckled with gold that get brighter with more light. Tough, it suits bright indoor spots, balconies and gardens. The name means \"gold and silver\", making it a popular gift for openings and housewarmings.","spec":"Indoor · Office","specs":[["Light","Bright spot with gentle sun; indoors, place next to a bright window — in low light the leaves lose their yellow spots"],["Watering","Water when the top 2–3cm of soil is dry, about twice a week; never leave water standing in the saucer"],["Soil","Loose, free-draining mix: clean soil with coco coir, burnt rice husk and worm castings"],["Feeding","Diluted NPK 20-20-20 once a month while the plant is putting out new leaves"],["Temperature & humidity","Suits the hot, humid climate of southern Vietnam, 22–35°C"],["Care level","Easy care"],["Growth rate","Moderate"],["Mature size","50cm–1.5m tall, prune to keep its shape"],["Pet safety","No — the white sap irritates skin and is toxic if chewed"],["Uses","Bright living rooms, balconies, gardens; a gift for shop openings"],["Propagation","Cuttings, air layering"],["Origin","Malaysia, Indonesia, Pacific islands"],["Scientific name","Codiaeum variegatum"],["Common pests & diseases","Mealybugs, red spider mites; drops leaves if suddenly moved or short of light"],["Best for","People who like coloured foliage, bright homes"]]}'::jsonb WHERE "slug" = 'vang-bac' AND "en" IS NULL;
