UPDATE "products" SET "en" = '{"name":"Dieffenbachia (Vạn niên thanh)","lead":"Dieffenbachia has broad dark-green leaves splashed with cream-white and a thick fleshy stem. Shade-tolerant and vigorous, it suits living rooms and offices. The sap irritates skin, so keep it out of reach of small children.","spec":"Office · Indoor","specs":[["Light","Bright indirect light, tolerates shade well; avoid harsh direct sun, which scorches the leaves"],["Watering","Water when the top 2–3cm of soil is dry, about 2–3 times a week; never leave water standing in the saucer"],["Soil","Loose, free-draining mix: clean soil with coco coir, burnt rice husk and worm castings"],["Feeding","Slow-release fertiliser or diluted NPK 20-20-20, once a month"],["Temperature & humidity","Best at 18–32°C, likes humidity; keep out of direct air-conditioner draughts"],["Care level","Easy care"],["Growth rate","Moderate"],["Mature size","40cm–1m tall"],["Pet safety","No — the sap irritates skin and is toxic if chewed (calcium oxalate crystals)"],["Uses","Living rooms, offices, lobbies"],["Propagation","Division, stem or tip cuttings"],["Origin","Central and South America"],["Scientific name","Dieffenbachia spp"],["Common pests & diseases","Root rot if waterlogged, mealybugs, red spider mites; yellow leaves after long periods of low light"],["Best for","Homes, offices"]],"fengshui":{"meaning":"The name means evergreen, health and longevity","placement":"Living room, east corner"}}'::jsonb WHERE "slug" = 'van-nien-thanh' AND "en" IS NULL;
